//! The lines each generated file opens with.

/// The header of a file that `writer` generates from `input`.
///
/// It names the writer, the input and the command that regenerates the file
/// (openspec rust-codegen, design section 5.3).
/// The file's own `//!` docs follow it.
pub(crate) fn header(writer: &str, input: &str) -> String {
    let mut text = format!("// @generated by {writer} from {input}.\n");
    text.push_str("// Regenerate with `mise run codegen`; do not edit.\n");
    text
}
